// Shared setup for the Module 7B lab.
//
// Three roles, three keypairs (generated by `npm run setup`):
//   merchant   - owns the plan
//   subscriber - pays
//   puller     - the merchant's collector key (listed on the plan)
//
// Wallet files use the Solana CLI's 64-byte JSON format, so you can also point
// any role at ~/.config/solana/id.json via the *_WALLET env vars.

import { address, createClient, createKeyPairSignerFromBytes, type Address, type KeyPairSigner } from "@solana/kit";
import { solanaLocalRpc } from "@solana/kit-plugin-rpc";
import { signer } from "@solana/kit-plugin-signer";
import { subscriptionsProgram } from "@solana/subscriptions";
import { findAssociatedTokenPda, TOKEN_PROGRAM_ADDRESS } from "@solana-program/token";
import { readFileSync, writeFileSync, existsSync } from "node:fs";

export const RPC_URL = process.env.RPC_URL ?? "https://api.devnet.solana.com";

// Devnet USDC (faucet.circle.com). Any SPL or Token-2022 mint without the
// excluded extensions (README Section 8) works.
export const TOKEN_MINT: Address = address(
  process.env.TOKEN_MINT ?? "4zMMC9srt5Ri5X14GAgXhaHii3GnPAEERYPJgZJDncDU"
);
export const TOKEN_DECIMALS = 6;

// Plan terms - lab step 1 changes these.
export const PLAN_ID = BigInt(process.env.PLAN_ID ?? "1");
export const PLAN_AMOUNT = 5_000_000n;    // 5 USDC per period
export const PLAN_PERIOD_HOURS = 720n;    // 30 days
export const PLAN_METADATA_URI = "https://example.com/plans/pro.json";

export const STATE_FILE = "./lab-state.json";

export async function loadSigner(role: "merchant" | "subscriber" | "puller"): Promise<KeyPairSigner> {
  const path = process.env[`${role.toUpperCase()}_WALLET`] ?? `./${role}-wallet.json`;
  if (!existsSync(path)) throw new Error(`${path} not found - run: npm run setup`);
  return createKeyPairSignerFromBytes(Uint8Array.from(JSON.parse(readFileSync(path, "utf-8"))));
}

// A Kit client with the subscriptions plugin, acting as `s`.
export function clientFor(s: KeyPairSigner) {
  return createClient()
    .use(signer(s))
    .use(solanaLocalRpc({ rpcUrl: RPC_URL }))
    .use(subscriptionsProgram());
}

export async function ataOf(owner: Address): Promise<Address> {
  const [ata] = await findAssociatedTokenPda({ mint: TOKEN_MINT, owner, tokenProgram: TOKEN_PROGRAM_ADDRESS });
  return ata;
}

// Small on-disk state so the numbered scripts can hand PDAs to each other.
export type LabState = { planPda?: string; subscriptionPda?: string };
export function readState(): LabState {
  return existsSync(STATE_FILE) ? JSON.parse(readFileSync(STATE_FILE, "utf-8")) : {};
}
export function writeState(patch: LabState) {
  writeFileSync(STATE_FILE, JSON.stringify({ ...readState(), ...patch }, null, 2));
}

export const ui = (base: bigint) => `${Number(base) / 10 ** TOKEN_DECIMALS} tokens`;
